    {
      "card_ids": ["C40"],
      "claim": "Meperidine absolute oral bioavailability was 0.61 in healthy volunteers versus IV, a direct human F measurement supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C55"],
      "claim": "Solifenacin absolute oral bioavailability was 88% in healthy volunteers after a 10 mg oral dose versus 5 mg IV, directly supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Encainide absolute oral bioavailability was 32 ± 7% in normal subjects, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
