      "card_ids": ["C08"],
      "claim": "Rasagiline absolute oral bioavailability was 36% in humans, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Etodolac absolute oral bioavailability was 0.80 in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C59"],
      "claim": "Viloxazine oral bioavailability was 85% in adult patients, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C54"],
      "claim": "Recainam absolute oral bioavailability was 84% after an 800 mg oral dose in healthy men, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Doxazosin absolute oral bioavailability was 65 ± 14% in young volunteers, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Indacaterol oral bioavailability from the gastrointestinal tract was approximately 24%, still at or above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C39"],
      "claim": "Praziquantel oral bioavailability was 27.2 ± 5.4% in patients, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "All retrieved experimental records with direct human absolute bioavailability measurements for structurally related small-molecule drugs report F values ≥20% (mostly 24–90%), and the highest-transfer analogues consistently support high oral bioavailability. No affirmative threshold-relevant evidence for F <20% is present, so the prediction is high.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule is available; all evidence comes from analogues.",
    "The query contains a fused furan ring and a neutral amide, which may confer different first-pass metabolic liability than the ionizable or more polar groups in the analogues."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

